//go:build usblink_local_remote

package connectioninstall

import (
	"bytes"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"io"
)

// Preferences contain intent only. Credentials and process-bound authorization
// are always regenerated by the normal enable path.
type localDebugPreference struct {
	Schema   int    `json:"schema"`
	OwnerSID string `json:"owner_sid"`
	Enabled  *bool  `json:"enabled"`
}

func localDebugPreferenceName(sid string) (string, error) {
	if !validPreparedUserSID(sid) {
		return "", fmt.Errorf("LOCAL_DEBUG_OWNER_INVALID")
	}
	sum := sha256.Sum256([]byte(sid))
	return "local-debug-preference-" + hex.EncodeToString(sum[:]) + ".json", nil
}

func decodeLocalDebugPreference(b []byte, sid string) (bool, error) {
	if _, err := localDebugPreferenceName(sid); err != nil {
		return false, err
	}
	if len(b) > 1024 {
		return false, fmt.Errorf("LOCAL_DEBUG_PREFERENCE_INVALID")
	}
	var p localDebugPreference
	d := json.NewDecoder(bytes.NewReader(b))
	d.DisallowUnknownFields()
	if d.Decode(&p) != nil || d.Decode(new(any)) != io.EOF || p.Schema != 1 || p.OwnerSID != sid || p.Enabled == nil {
		return false, fmt.Errorf("LOCAL_DEBUG_PREFERENCE_INVALID")
	}
	return *p.Enabled, nil
}
